ZTEST(lib_json_test, test_json_string_array_size)
{
	int ret;
	struct elt elt_ts;
	char encoded[] = "{\"name_buf\":\"a12345678\"}";

	ret = json_obj_parse(encoded, strlen(encoded),
			     elt_descr,
			     ARRAY_SIZE(elt_descr),
			     &elt_ts);

	/* size of name_buf is 10 */
	zassert_str_equal(elt_ts.name_buf,
